INTERNAL_CONFLICTS=[
dict(id='KIC-01',severity='minor',items=['KERNEL-0109','KERNEL-0341','KERNEL-0338'],where=['§3.3 clear regions rule 2','§3.10 stored-references row'],claim="§3.3 rule 2 says no two vertices carry one anchor key, citing '§3.10's one-vertex-per-ordinal check'; no §3.10 row has that name, and the nearest row (stored references resolve: exactly one vertex per ordinal) runs at 'stage end, save' - after the coarse batch has stripped the anchor contact names (§3.3 rule 3; §3.9: anchors never reach a snapshot) - so no §3.10 check ever sees an anchor row; the prepared-contacts row checks stripping, not uniqueness. Uniqueness rests on the allocation rule and §13.1's permuted-ops test.",required="Either name the check that covers anchor uniqueness batch-locally (e.g. extend the prepared-contacts row: 'no two vertices carry one anchor key') or cite the §13.1 test and the allocation rule instead of §3.10."),
dict(id='KIC-02',severity='minor',items=['KERNEL-0196','KERNEL-0215','KERNEL-0216'],where=['§3.4 Arenas, keys and services','§3.4 Transient arenas'],claim="§3.4 says resolve, pointLocate and faceNeighbours take an ArenaKey (a PlatKey or a TransientKey); the transient-arena paragraph lists as its services only booleans, offsetFace, insetRing, obb, lir, sideRuns, skeleton, faceNeighbours and area2, and a transient arena has no role rows or entities, so a role-based FaceRef/ChainRef/EdgeSetRef/VertexRef cannot resolve on it; §14's Kernel says a transient arena is read through readBack and view. Whether resolve and pointLocate are offered on a transient arena is ambiguous.",required="State the transient arena's full service list once (including or excluding resolve, pointLocate, view) and make the ArenaKey sentence agree."),
dict(id='KIC-03',severity='minor',items=['KERNEL-0100','KERNEL-0167','KERNEL-0266'],where=['§3.3 One level per transaction','§3.4 warp signature','§3.6 Moves'],claim="A warp batch has two level sources: KernelTx.level ('a warp batch moves vertices of every level >= its own') and warp's fromLevel argument ('every vertex of level >= fromLevel'); nothing states they must be equal or which governs.",required="State that a warp batch's KernelTx.level equals its fromLevel (or which one governs)."),
dict(id='KIC-04',severity='minor',items=['KERNEL-0168','KERNEL-0266','KERNEL-0269'],where=['§3.4 pinVertices','§3.6 Moves, Held vertices'],claim="pinVertices: 'smoothing, simplification and cutting keep the vertex, warp does not'; §3.6: smoothing of committed geometry IS a warp 'under the same rules', and kernel-pinned vertices 'move with everything else unless held'. The mechanism by which a smoothing warp keeps kernel-pinned vertices (the smoother's field being zero there) is not stated.",required="State that the smoother's displacement field is zero at every kernel-pinned vertex (or that pinned vertices join the held set for a smoothing warp)."),
dict(id='KIC-05',severity='minor',items=['KERNEL-0165','KERNEL-0102','KERNEL-0285'],where=['§3.4 corridorUnion comment','§3.3 kept content','§3.7 kerb'],claim="§3.4's corridorUnion comment says 'kept faces inside them are holes (§3.3)', while §3.3 re-parents each kept face into the new face containing it (nesting holds) and §3.7 says a kept face 'must lie wholly inside one resulting L2 face'; a nested child face is not a hole of its L2 parent.",required="Replace 'are holes' by 'are kept content nested in the L2 face that contains them (§3.3)' or define the sense of 'hole'."),
dict(id='KIC-06',severity='minor',items=['KERNEL-0072','KERNEL-0333'],where=['§3.2 (6)','§3.10 simplicity row'],claim="§3.2 (6) justifies area2's exact double return by 'every face ring is simple, §3.10', but §3.10's row is 'faces simple except declared antennae' - a face with an antenna has a non-simple (retracing) ring. The bound still holds (retraced edges add zero area) but the stated reason is false for antenna faces.",required="Reword to 'every face ring is simple or retraces only declared antennae, which add no area'."),
dict(id='KIC-07',severity='minor',items=['KERNEL-0057','KERNEL-0302','KERNEL-0312','KERNEL-0184'],where=['§3.2 (1)','§3.8','§3.4 RegularFit.targets'],claim="§3.2 (1) says intermediate rational points - 'crossings, offsets, circumcentres, skeleton nodes' - are 'immediately placed on the lattice'; §3.8 keeps skeleton output off every arena (derived, cached, validated with nodes rounded to the millimetre) and only arcs a stage inserts pass snap; RegularFit.targets are likewise 'values, never arena coordinates'.",required="Restrict (1) to points that become arena geometry: they are placed on the lattice when they enter an arena (by insertChain/snap); derived values (skeleton nodes, fit targets) stay doubles until then."),
dict(id='KIC-08',severity='minor',items=['KERNEL-0322'],where=['§3.9 Chunks'],claim="'Each static-index partition (§3.3) is one chunk holding ... its edges of level >= 2 ... and its face rows of level >= 2' - but the L0 and L1 static partitions (one per arena, §3.3) hold only level <= 1 items, which the separate level-<=1 routes chunk already holds; whether the L0/L1 partitions are chunks of their own is ambiguous.",required="Say 'each L2-L4 static-index partition is one chunk'."),
]
CROSS_CONFLICTS=[
dict(id='KXC-01',severity='minor',items=['KERNEL-0025','KERNEL-0254'],other='§5.2 F-NUM row (determinism unit)',claim="§3.1: E_OUT_OF_RANGE is 'a caller bug, reported with its stream key, never stored'; §3.6: a mandatory chain can be rejected only by non-precision codes. §5.2's F-NUM row lists E_OUT_OF_RANGE among the detections of an optional chain's 'precision failure' with a re-propose ladder ('mandatory chains never reach it'). The two classify one code differently (caller bug vs precision failure).",ruling_hint="Base canonical home of the code is §3.1: §5.2 F-NUM should drop E_OUT_OF_RANGE (or §3.1 should say an optional chain's out-of-range point is handled by F-NUM)."),
dict(id='KXC-02',severity='major',items=['KERNEL-0064','KERNEL-0065','KERNEL-0349'],other='§4.7 plot tables (pipeline unit); §5.2 F-PLOT; §3.10',claim="§3.2 (2) states 'The class floors come from the stage tables: minPlotWidth = 2.5 m, minInteriorAnglePlot = 12 deg ... minCorridor per class', but no stage table, base section or volume carries these names or the 2.5 m value (grep: they occur only in §3.2 (2)); §4.7 says 'the minimum plot width' and 'meets the class's floors in width and area (§3.10)', §3.10 says 'Class floors are the stages' invariants, stated as §3.2 (2) says', §5.2 F-PLOT says 'wedge angle < 12 deg'. The home is circular and minCorridor has no value anywhere (an undefined constant).",ruling_hint="Give the floors one home: a table row in §4.7 (pipeline) with minPlotWidth 2.5 m, minInteriorAnglePlot 12 deg, minCorridor per class with values, read by §3.10's class-floor check; §3.2 (2) keeps only the rule that floors are widths/areas/angles and never minEdge."),
dict(id='KXC-03',severity='minor',items=['KERNEL-0103'],other='§2.2 rule 6 (model unit); §7.2 (determinism unit)',claim="§3.3: 'only locked or pinned content is a conflict (§2.2 rule 6)'; §2.2 rule 6 says 'what survives the clear - locked or pinned entities, returned as conflicts ... is §3.3's'. Each cites the other as the home; the rule on locked/pinned entities is §7.2's, cited by neither.",ruling_hint="Cite §7.2 for locks and pins in both places; one of §2.2 rule 6 / §3.3 states the clear rule, the other references it."),
dict(id='KXC-04',severity='minor',items=['KERNEL-0312','KERNEL-0313'],other='§5.2 F-SKELETON row (determinism unit)',claim="F-SKELETON's detection restates §3.8's validator as three checks (non-planar, non-monotone faces, inconsistent heights) and omits check (4) (connected, exactly h independent cycles for h holes); §3.8 never names its failure class F-SKELETON (the hook is one-ended in naming).",ruling_hint="F-SKELETON cites '§3.8's four post-conditions' instead of restating; §3.8 names F-SKELETON beside W_DOWNGRADE."),
dict(id='KXC-05',severity='minor',items=['KERNEL-0043','KERNEL-0047','KERNEL-0048','KERNEL-0052','KERNEL-0054'],other='§5.4 generation report (determinism unit)',claim="§5.4's kernel.warnings comment enumerates 8 of the 12 Warning codes (W_ATTRACTED, W_STRETCH_SHARED, W_WEDGE_ROUTED, W_SNAP_PASSES, W_ACUTE_CORNER, W_SLIVER_RETYPED, W_HEIGHT_CLAMPED, W_CUT_SLID); W_PLACED, W_PROMOTED, W_STEINER and W_DOWNGRADE are absent (W_DOWNGRADE presumably counted as kernel.downgrades).",ruling_hint="§5.4 reads 'every Warning code of §3.1' (one reference) and says kernel.downgrades counts W_DOWNGRADE."),
]
